final dio = Dio(BaseOptions(baseUrl: 'https://endpoint/'));
final queryBuilder = GraphQLQueryBuilder(
  transformer: (q) => q.replaceAll(RegExp(r'\s+'), ' ').trim(),
);
await dio.post<dynamic>(
  'graphql/',
  data: queryBuilder.build(
    queryA,
    UserQueryPayloadA(27, 'John'),
  ),
);
